"""Root translations of visually checked full-rule corrections, six-team batch."""
import json
from pathlib import Path
ROOT=Path(__file__).parent
q=json.loads((ROOT/'inventory/critic-rules-six-teams-2026-10-05.json').read_text(encoding='utf8'))['queue']
cards=json.loads((ROOT/'ru-images-all-reviewed.json').read_text(encoding='utf8'));out=[]
def patch(n,id=None):
 x=q[n];id=id or x['localIds'][0]
 p={'id':id,'expectedTitle':cards[id]['titleEnglish'],'team':x['team'],'source':{**x['source'],'checkedOn':'2026-10-05','basis':'Full official rules plus visually checked effective errata'}};out.append(p);return p
def body(n,ru,heading='Rule',titles=None,id=None,en=None):
 p=patch(n,id);u={'heading':heading,'english':en or q[n]['currentEnglish'],'russian':ru}
 if titles:u['proseTitles']=titles
 p['blocks']=[u];return p
def add(p,heading,ruHeading,en,ru,titles=None):
 u={'heading':heading,'headingRussian':ruHeading,'english':en,'russian':ru,'append':True}
 if titles:u['proseTitles']=titles
 p.setdefault('blocks',[]).append(u)

body(0,'Можно игнорировать ухудшение HIT оружия дружественных оперативников Культа Хаоса (CHAOS CULT), вызванное ранением (Injured). Каждый раз, когда по раненому дружественному оперативнику Культа Хаоса стреляют, вы можете перебросить один свой защитный кубик.')
body(1,'Когда этот оперативник сражается или отвечает в ближнем бою (Fight / Retaliate), вражеские оперативники не могут помогать (Assist). При первом нанесении удара (Strike) в этой последовательности также нанесите 1 урона каждому другому вражескому оперативнику в дистанции контроля этого оперативника. Если этот оперативник — Терзаемый (TORMENT), вместо этого нанесите D3 урона.','6. Barbed',['Barbed'])
body(2,'Примените эту тактическую уловку (Firefight Ploy) во время активации дружественного Мутанта (MUTANT) или Терзаемого (TORMENT) Культа Хаоса, до или после выполнения им действия. В эту активацию он может выполнить два действия «Сражаться» (Fight), одно из которых может быть бесплатным.')
patch(3)['baseSizeNote']='Диаметр базы: 28 мм'
body(4,'При определении контроля маркера в пределах 4 дюймов от этого оперативника считайте суммарный APL дружественных оперативников Братьев Выводка (BROOD BROTHER), оспаривающих этот маркер, на 1 выше, если хотя бы один дружественный оперативник Братьев Выводка его оспаривает. Это не изменение характеристики APL: другие модификаторы суммируются с этим правилом.','Cult Icon',['Cult Icon'],en=q[4]['currentEnglish'].split('\n\n')[0].removeprefix('Cult Icon: '))
# Broodmind Devotion already has the correct Fight + Explosives exclusions. Mind Control is struck out.
body(5,'ПСИХИЧЕСКОЕ (PSYCHIC). Выберите вражеского оперативника, являющегося допустимой целью (Valid Target) для этого оперативника. До конца активации выбранного оперативника вычитайте 1 из его APL. Нельзя выполнять это действие в дистанции контроля вражеского оперативника.','Telepathic Overload · 1AP',['Telepathic Overload'],en=q[5]['currentEnglish'])
body(6,'Стратегический гамбит (STRATEGIC GAMBIT), если этот оперативник находится в зоне боя. Выберите одного вражеского оперативника: он получает один ваш жетон перекрёстного огня (Crossfire).','Coordinate · Strategic Gambit',['Coordinate'])
body(7,'Когда дружественный оперативник Братьев Выводка (кроме Патриарха, PATRIARCH) выведен из строя во время боя или ответного боя, если у вас остались неразыгранные успехи, можно бросить один D6. Определите успех так, как на шаге броска кубиков атаки (Roll Attack Dice) этой последовательности: используйте HIT того же оружия, без перебросов. При успехе можно нанести врагу удар одним из своих неразыгранных обычных успехов; при критическом успехе D6 можно использовать любой свой неразыгранный успех. Затем дружественного оперативника убирают из зоны боя.')
body(8,'Выберите одного дружественного оперативника Братьев Выводка (кроме Патриарха) в дистанции контроля этого оперативника: выбранный оперативник восстанавливает до 2D3 потерянных ран. Нельзя выбирать оперативника, к которому в этом раунде применяли правило «Медик!» (Medic!).\nЭто действие нельзя выполнять в дистанции контроля вражеского оперативника.','Medikit · 1AP',['Medikit'])
for id in q[9]['localIds']:patch(9,id)['keyword']=['TYRANID','ТИРАНИД (TYRANID)']
p=patch(10,q[10]['relatedIds'][0]);add(p,'Rules Commentary','Разъяснения правил',q[10]['currentEnglish'],'«Безжалостная координация» (Ruthless Coordination): Волчий скаут (WOLF SCOUT) в 3 дюймах, которому «Призыв бури» (Call the Storm) даёт заслонение (Obscured), не считается заслонённым. Если цель целиком в дыму, а находящийся между стрелком и целью дружественный оперативник в пределах 2 дюймов от неё, дым и подобные правила не действуют.\n«Преданность культу» (Cult Devotion): если оперативник выведен из строя во время действия, его характеристики не меняются в ходе этого действия.')
resource='На шаге готовности (Ready) каждой фазы стратегии после первой получайте очки находчивости (Resourceful) по числу дружественных оперативников Хернкин-ягирей (HERNKYN YAEGIR) в зоне боя, находящихся вне дистанции контроля врагов: 5 и более — 2 очка; 1–4 — 1 очко; 0 — 0 очков. В конце каждого раунда сбросьте оставшиеся очки.\nВ каждую активацию каждого дружественного оперативника можно потратить 1 очко находчивости, выбрав один эффект:\n• До или после действия, если оперативник вне дистанции контроля врагов: увеличьте его APL на 1 до конца этой активации.\n• При активации, если оперативник вне дистанции контроля врагов: восстановите ему до D3+1 потерянных ран.'
resourceEn=q[11]['currentEnglish'].replace('0–2 = 0','0 = 0')
for id in q[11]['localIds']:
 p=body(11,resource,id=id,en=resourceEn)
 if id=='4cf632768c552346':p['blocks'].append({'heading':'OPERATIVES · RESOURCEFUL POINTS','russian':'','columnsRussian':['Оперативники','Очки находчивости'],'rowsRussian':[['5+','2'],['1–4','1'],['0','0']]})
p=body(12,'На шаге готовности каждой фазы стратегии после первой, если этот оперативник находится в зоне боя и вне дистанции контроля врагов, получите 1 очко находчивости.','Veteran Adventurer',['Veteran Adventurer'],en=q[12]['currentEnglish'].split('Bolt shotgun')[0].removeprefix('Veteran Adventurer: ').strip());p['weapons']=[{'name':'Bolt shotgun (long range)','dmg':'2/3'}]
p=body(13,'Когда вы тратите очко находчивости на этого оперативника, следующие правила имеют приоритет:\n• Если увеличиваете его APL на 1, эффект длится до начала его следующей активации.\n• Если восстанавливаете потерянные раны, он восстанавливает до 4 ран вместо обычного количества.','Intrepid',['Intrepid'],en=q[13]['currentEnglish'].split('Intrepid: ')[1]);p['weapons']=[{'name':'Bolt shotgun (long range)','dmg':'2/3'}]
body(14,'Когда дружественный оперативник Хернкин-ягирей сражается либо отвечает в ближнем бою с приказом «Скрытность» (Conceal), увеличьте ATK его оружия ближнего боя на 1, максимум до 4, и добавьте этому оружию правило «Сбалансированное» (Balanced). Если оружие уже имеет Balanced, вместо него оно получает «Непрерывное» (Ceaseless).')
body(15,'Примените эту тактическую уловку, когда вражеский оперативник заканчивает действие «Атака» (Charge) в дистанции контроля дружественного оперативника Хернкин-ягирей. Выберите другого дружественного оперативника Хернкин-ягирей, видимого первому и в пределах 6 дюймов от него; выбранный оперативник должен находиться вне дистанции контроля врагов. Он может бесплатно выполнить действие «Стрелять» (Shoot).\nВ этом действии можно стрелять только по атакующему врагу, несмотря на то что тот находится в дистанции контроля дружественного оперативника. Нельзя выбирать осколочную или противотанковую гранату, а также оружие с правилом «Взрыв» (Blast) или «x дюймов Разрушительное x» (x″ Devastating x).')
body(16,'Дружественные оперативники Хернкин-ягирей получают плазменный нож (Plasma Knife), указанный в таблице. У некоторых оперативников уже есть это оружие с лучшими характеристиками: используйте лучшую версию, и на весь бой она также получает правило «Сбалансированное» (Balanced).')
body(17,'До двух раз за раунд, когда дружественный оперативник Хернкин-ягирей выполняет действие «Стрелять» и выбирает болтовый дробовик — дальний огонь (Bolt shotgun, long range), можно применить это правило. До конца действия улучшите HIT этого оружия на 1, увеличьте обе характеристики DMG на 1 и добавьте правило «Точное 1» (Accurate 1).')
body(18,'Примените эту тактическую уловку, когда дружественный оперативник Хернкин-ягирей выведен из строя. До его удаления из зоны боя уберите свой прежний маркер павшего родича (Fallen Kin), если он есть, и поставьте маркер в дистанции контроля этого оперативника. Затем оперативника убирают как обычно.\nКогда дружественный оперативник Хернкин-ягирей в пределах 3 дюймов от вашего маркера павшего родича стреляет, сражается или отвечает в ближнем бою, на шаге броска кубиков атаки можно сохранить один провал как обычный успех вместо сброса либо один обычный успех как критический.')
body(19,'Примените эту тактическую уловку при активации дружественного оперативника Хернкин-ягирей. Выберите другого готового (Ready) дружественного оперативника Хернкин-ягирей, видимого первому и в пределах 3 дюймов от него. Когда первый оперативник станет отыгравшим (Expended), можно активировать выбранного оперативника до активации противника. Когда выбранный оперативник станет отыгравшим, противник активирует оперативника по обычным правилам.\nНи один из двух оперативников не может быть Бомбастом (BOMBAST), если в этом раунде использовался его стратегический гамбит «Переговоры Ротлока» (Wroughtlock Negotiation).')
p=patch(20);p['weapons']=[{'name':'Big choppa','atk':5,'wrEnglish':'—','wrRussian':'—'},{'name':'Power klaw','wrEnglish':'Brutal, Shock','wrRussian':'«Жестокое» (Brutal); «Шок» (Shock)'}];add(p,'Krumpin’ Time','Пора крушить','This operative can perform two Fight actions during its activation.','Этот оперативник может выполнить два действия «Сражаться» (Fight) в свою активацию.',['Krumpin’ Time',"Krumpin' Time"])
p=patch(21);p['weapons']=[{'name':'Dakka shoota (short range)','wrEnglish':'Range 9", Ceaseless','wrRussian':'Дальность 9 дюймов (Range 9″); «Непрерывное» (Ceaseless)'}]
body(22,'Уберите правило «Дальность» (Range) у следующего стрелкового оружия дружественных оперативников Коммандос (KOMMANDO): шокка-пистолет (Shokka pistol) и слагга (Slugga).')
p=patch(23);p['weapons']=[{'name':'Burna (deluge)','wrEnglish':'Range 4", Saturate, Seek, Torrent 0"*','wrRussian':'Дальность 4 дюйма (Range 4″); «Насыщение» (Saturate); «Обнаружение» (Seek); «Поток 0 дюймов» (Torrent 0″)*'}];add(p,'Torrent 0″*','Поток 0 дюймов',q[23]['currentEnglish'].split('*Torrent 0″')[1],'Нельзя выбирать вторичные цели. Однако оружие сохраняет правило «Поток» (Torrent) для всех остальных взаимодействий с правилами, например «Тесная крепость» (Condensed Stronghold).')
expend='Игнорируйте этого оперативника при подсчёте операции уничтожения / ликвидации (Kill / Elimination Op) противника: как при его выведении из строя, так и при определении вашего начального числа оперативников. Также игнорируйте его для условий победы и начисления VP, требующих от оперативников «сбежать», «выжить» или быть выведенными из строя врагами. Это относится и к самому событию, и к определению необходимого количества таких оперативников.'
body(24,expend,'Expendable',['Expendable'])
p=patch(25,q[25]['relatedIds'][0]);add(p,'Rules Commentary','Разъяснение правил',q[25]['currentEnglish'],'Если бомбовый сквиг (BOMB SQUIG) Коммандос выведен из строя при бое через дверь (Door Fight), бойницу (Hatchway Fight) или через дверь, игнорируемую при определении видимости для дистанции контроля, другой участвующий оперативник не становится вторичной целью выстрела по правилу «Бум!» (Boom!).')
body(26,'Когда дружественный Кошмарный громила (NIGHTMARE HULK) Заражённых Геллерпокс (GELLERPOX INFECTED), кроме Мутоидной мелочи (MUTOID VERMIN), сражается или отвечает в ближнем бою, противник не может сохранять результаты 3 как успехи.')
body(27,'После раскрытия этого варианта снаряжения добавьте в отряд на этот бой четырёх оперативников Мутоидной мелочи (MUTOID VERMIN) Заражённых Геллерпокс.')
body(28,'Когда этот оперативник выведен из строя, до его удаления из зоны боя бросьте по одному D6 отдельно за каждого видимого вражеского оперативника в пределах 2 дюймов от него. При результате 4+ нанесите этому врагу 1 урона.','Caustic Demise',['Caustic Demise'])
body(29,'В каждую активацию / контратаку дружественного оперативника Банды крушил (WRECKA KREW), кроме Бомбового сквига, с приказом «Бой» (Engage), когда он впервые выполняет одно из действий «Атака» (Charge), «Стрелять» (Shoot) или «Сражаться» (Fight), кроме действий по правилу «Дозор» (Guard), увеличьте его APL на 1 до начала следующей активации.')
body(30,'Когда дружественный оперативник Банды крушил стреляет, сражается или отвечает в ближнем бою, на шаге броска кубиков атаки получите по 1 очку крушил (Wrecka point) за каждый сохранённый результат 6. Можно потратить до 2 очков крушил: за каждое сохраните один провал как обычный успех вместо сброса. Бомбовые сквиги не могут тратить эти очки.\nОдновременно у вас может быть не больше 6 очков крушил. В одном действии можно получать и тратить очки в любом порядке. Если вы начали действие с 6 очками, в этом действии их можно только тратить.')
body(31,'Выберите до двух разных допустимых целей вне дистанции контроля дружественных оперативников. Стреляйте этим оружием по обеим основным целям в любом порядке, затем по оставшимся вторичным целям таким же образом. Каждую последовательность бросков разыгрывайте отдельно. По каждой цели, основной или вторичной, можно стрелять лишь один раз в это действие.','Salvo*',['Salvo'])
body(32,'Когда впервые за бой вы должны нанести урон врагу этим профилем оружия, вместо обычного урона нанесите этому врагу и каждому другому оперативнику в его дистанции контроля D6+6 урона при обычном успехе либо 2D6+6 при критическом успехе. Бросайте отдельно за каждого оперативника. Затем действие заканчивается: получите 1 очко крушил плюс ещё по 1 за каждого оперативника, выведенного из строя в ходе этого действия.\nУрон от этого правила нельзя игнорировать или уменьшать.','Detonate*',['Detonate'])
body(33,expend,'Expendable',['Expendable'])
body(34,'Уменьшите MOVE дружественных оперативников Банды крушил на 1 дюйм и улучшите SAVE на 1. Бомбовые сквиги исключаются. Эффект не суммируется с правилом «Защитное» (Protective) переносной баррикады (Portable Barricade) из общего снаряжения.')
p=patch(35,q[35]['relatedIds'][0]);add(p,'Rules Commentary','Разъяснения правил',q[35]['currentEnglish'],'Бомбовый сквиг: другой оперативник в бою через дверь / бойницу или при игнорировании двери для видимости не становится вторичной целью «Бум!» (Boom!). Исключение: бой через бойницу, другой оперативник видим и в пределах 2 дюймов, а сквиг использует «Кабум!» (Kaboom!).\nКруша (KRUSHA), «Сокрушение» (Smash): если маркер, способный закончить действие перемещённого врага, находится в дистанции контроля врага, но вне дистанции контроля Круши, действие «Сражаться» не заканчивается.\n«Под завязку» (Tanked Up): бонус APL за действие «Атака» применяется в начале действия, до перемещения.')
(ROOT/'ru-current-updates-six-teams.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
